// Monta a pagina de confirmacao a partir do ticket que veio no link.
//
// NAO confere a assinatura: quem confere e o agente, no POST. Aqui o payload e
// so texto para exibir — um ticket forjado renderiza uma pagina bonita e morre
// no agente do mesmo jeito. Manter a validacao num lugar so evita as duas
// implementacoes discordarem.
//
// Este ramo e deliberadamente INERTE: nada aqui toca no host. O prefetch de
// preview de link (WhatsApp, Cloudflare) abre esta URL sozinho, e se o GET
// aprovasse, um deploy sairia sem ninguem ter tocado em nada.

const entrada = $input.first()?.json || {}
const t = entrada.query?.t || ''
const ensaio = entrada.query?.ensaio === '1'

const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;')

function abrirTicket(bruto) {
  try {
    const corpo = String(bruto).split('.')[0]
    if (typeof Buffer !== 'undefined') return JSON.parse(Buffer.from(corpo, 'base64url').toString('utf8'))
    const b64 = corpo.replace(/-/g, '+').replace(/_/g, '/')
    return JSON.parse(decodeURIComponent(escape(atob(b64))))
  } catch (e) {
    return null
  }
}

const ESTILO = `*{box-sizing:border-box}
body{margin:0;padding:24px 16px;font:16px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
background:#0f1115;color:#e6e8ee;display:flex;justify-content:center}
.cartao{width:100%;max-width:460px;background:#171a21;border:1px solid #262b36;border-radius:14px;padding:24px}
h1{margin:0 0 4px;font-size:20px;letter-spacing:-.01em}
.sub{margin:0 0 20px;color:#8b93a7;font-size:14px}
.caixa{background:#0f1115;border:1px solid #262b36;border-radius:10px;padding:14px;margin:0 0 20px;font-size:14px}
.caixa div{display:flex;justify-content:space-between;gap:12px;padding:3px 0}
.caixa span{color:#8b93a7}
ul{margin:8px 0 0;padding-left:18px;color:#8b93a7;font-size:13px}
label{display:block;font-size:13px;color:#8b93a7;margin:0 0 6px}
input[type=text]{width:100%;padding:11px 12px;font-size:16px;border-radius:9px;
border:1px solid #39404f;background:#0f1115;color:#e6e8ee}
input[type=text]:focus{outline:none;border-color:#d92e2e}
button{width:100%;margin-top:16px;padding:14px;font-size:16px;font-weight:600;border:0;border-radius:9px;
background:#d92e2e;color:#fff;cursor:pointer}
button:disabled{opacity:.5;cursor:default}
.aviso{margin-top:14px;font-size:12px;color:#8b93a7;text-align:center}
.erro{color:#ff8b8b}
.ok{color:#54c98a}
@media(prefers-color-scheme:light){
body{background:#f6f7f9;color:#1a1d24}
.cartao{background:#fff;border-color:#e2e5ea}
.caixa{background:#f6f7f9;border-color:#e2e5ea}
input[type=text]{background:#fff;border-color:#cdd2da;color:#1a1d24}
}`

function pagina(titulo, corpo) {
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<meta name="robots" content="noindex,nofollow">'
    + '<title>' + esc(titulo) + '</title><style>' + ESTILO + '</style></head>'
    + '<body><div class="cartao">' + corpo + '</div></body></html>'
}

const p = abrirTicket(t)

if (!t || !p) {
  return [{ json: { html: pagina('Link invalido',
    '<h1 class="erro">Link invalido</h1><p class="sub">Este link nao veio de um relatorio do Lidimus Update. '
    + 'Use o link da mensagem mais recente no WhatsApp.</p>') } }]
}

if (p.exp && p.exp * 1000 < Date.now()) {
  return [{ json: { html: pagina('Link vencido',
    '<h1 class="erro">Link vencido</h1><p class="sub">Links de aprovacao tem validade curta de proposito. '
    + 'O proximo relatorio traz um novo — ou rode <code>pnpm sandbox:ok</code> na maquina.</p>') } }]
}

const arquivos = (p.a || []).map((a) => '<li>' + esc(a) + '</li>').join('')
const mais = p.n > (p.a || []).length ? '<li>...e mais ' + (p.n - (p.a || []).length) + '</li>' : ''

const corpo = '<h1>Aprovar promocao</h1>'
  + '<p class="sub">' + (ensaio
    ? 'ENSAIO: roda o deploy em dry-run, sem tocar na producao.'
    : 'Confirmar grava o <code>sandbox:ok</code> e sobe para producao agora.') + '</p>'
  + '<div class="caixa">'
  + '<div><span>commit</span><b>' + esc(p.c) + '</b></div>'
  + '<div><span>arquivos alterados</span><b>' + esc(p.n) + '</b></div>'
  + (p.f ? '<div><span>commits a publicar</span><b>' + esc(p.f) + '</b></div>' : '')
  + (arquivos ? '<ul>' + arquivos + mais + '</ul>' : '')
  + '</div>'
  + '<form method="POST" action="lidimus-aprovar-confirmar" onsubmit="this.b.disabled=true;this.b.textContent=\'Enviando...\'">'
  + '<input type="hidden" name="t" value="' + esc(t) + '">'
  + (ensaio ? '<input type="hidden" name="dryRun" value="1">' : '')
  + '<label for="d">O que foi validado no sandbox</label>'
  + '<input type="text" id="d" name="descricao" required maxlength="200" value="' + esc(p.d) + '">'
  + '<button name="b" type="submit">' + (ensaio ? 'Rodar ensaio' : 'Aprovar e subir agora') + '</button>'
  + '</form>'
  + '<p class="aviso">Essa descricao vai para o corpo do commit e para o relatorio.</p>'

return [{ json: { html: pagina('Aprovar promocao', corpo) } }]

// Traduz a resposta do agente numa pagina, e decide se o deploy segue.
//
// O agente responde rapido de proposito (ele so grava o marcador), entao da
// para responder ao celular ANTES de comecar o build — o relatorio do deploy
// chega depois, pelo WhatsApp de sempre.

const r = $input.first()?.json || {}
const aprovado = r.ok === true
const pedido = $('Recebe aceite').first()?.json?.body || {}
const dryRun = pedido.dryRun === '1'

const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;')

const ESTILO = `body{margin:0;padding:24px 16px;font:16px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
background:#0f1115;color:#e6e8ee;display:flex;justify-content:center}
.cartao{width:100%;max-width:460px;background:#171a21;border:1px solid #262b36;border-radius:14px;padding:24px}
h1{margin:0 0 8px;font-size:20px}
p{margin:0 0 12px;color:#8b93a7;font-size:14px}
.erro{color:#ff8b8b}.ok{color:#54c98a}
@media(prefers-color-scheme:light){body{background:#f6f7f9;color:#1a1d24}.cartao{background:#fff;border-color:#e2e5ea}}`

const corpo = aprovado
  ? '<h1 class="ok">' + (dryRun ? 'Ensaio iniciado' : 'Aprovado') + '</h1>'
    + '<p>' + (dryRun
      ? 'O deploy vai rodar em dry-run. A producao NAO sera tocada.'
      : 'O deploy comecou. Ele ainda passa por todos os gates de sempre (disco, fila vazia, testes, migrations) e pode ser adiado por um deles.') + '</p>'
    + '<p>O relatorio chega no WhatsApp quando terminar. Pode fechar esta pagina.</p>'
    + '<p>Aprovado: <b>' + esc(r.marcador?.descricao) + '</b></p>'
  : '<h1 class="erro">Nao aprovado</h1>'
    + '<p>' + esc(r.motivo || r.erro || 'o agente do host nao respondeu — confira se o pnpm update:agente esta rodando') + '</p>'
    + '<p>A producao nao foi tocada.</p>'

const html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1">'
  + '<title>Lidimus Update</title><style>' + ESTILO + '</style></head>'
  + '<body><div class="cartao">' + corpo + '</div></body></html>'

return [{ json: { html, aprovado, dryRun } }]

// Lembrete da noite: pega o esquecimento antes do run das 5h.
//
// Fica CALADO quando nao ha o que aprovar. Um lembrete que chega todo dia vira
// ruido e para de ser lido justamente no dia em que importa.

const DESTINO = '5511947250110'
const p = $input.first()?.json || {}

if (!p.temMudanca || p.jaAprovado) return []

const arquivos = p.arquivos || []
const linhas = ['*Lidimus Update - lembrete*', '']
linhas.push('Tem trabalho no sandbox sem aprovacao. Do jeito que esta, o run das 5h nao vai subir nada.')
linhas.push('', '📝 ' + arquivos.length + ' arquivo(s) alterado(s) em ' + String(p.commit || '').slice(0, 7))
for (const a of arquivos.slice(0, 3)) linhas.push('   • ' + a)
if (arquivos.length > 3) linhas.push('   • ...e mais ' + (arquivos.length - 3))
if (p.commitsAFrente) linhas.push('   ' + p.commitsAFrente + ' commit(s) ainda nao publicado(s)')

if (p.url) {
  linhas.push('', '👉 Aprovar e subir agora:', p.url)
  linhas.push('_o link vale ate ' + p.validoAteTexto + '_')
}
linhas.push('', '_Ou rode pnpm sandbox:ok na maquina, e o deploy sai as 5h._')

return [{ json: { number: DESTINO, texto: linhas.join('\n') } }]
